(18, NULL, 14, 1, 31, 9, 9, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Mike\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"mikekevin.estimator@gmail.com\"},\"subject\":{\"field_name\":\"Subject\",\"field_type\":\"Input\",\"value\":\"Share Your Plans for a Painting Estimate\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hi,\\r\\n\\r\\nI\\u2019m Mike Kevin, Painting Project Estimator at All Pro Estimation LLC.\\r\\nWe provide painting estimates and quantity takeoffs to help contractors and builders manage projects and costs.\\r\\n\\r\\nOur Services & Components Include:\\r\\n\\r\\nInterior Painting \\u2013 Paint, primer, rollers, brushes\\r\\nExterior Painting \\u2013 Paint, coatings, sealants\\r\\nSurface Preparation \\u2013 Sanding, putty, fillers, primer\\r\\n\\r\\n\\ud83d\\udcc4 Share your plans or PDFs for an estimate.\\r\\n\\r\\nBest regards,\\r\\nMike Kevin\\r\\nAll Pro Estimation LLC\"}}', '103.145.185.187', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36', NULL, '2026-03-30 16:25:57', '2026-03-30 16:25:57', 'pending'),
