(82, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Kirsten Helfer\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"09830152514\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"helferkirsten@gmail.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello,\\r\\n\\r\\nI came across your website and really liked what you\'re doing.\\r\\n\\r\\nWhile browsing, I had a few ideas on how the design could be improved to make it more engaging and visually appealing. So I went ahead and created a quick redesign mockup for you. Its completely free.\\r\\n\\r\\nIt\\u2019s just a concept, but it shows how your site could look with a more modern and user-friendly approach.\\r\\n\\r\\nIf you\'re interested, I\\u2019d love to share it with you and get your thoughts.\\r\\n\\r\\nThanks for your time!\\r\\n\\r\\nCheers,\\r\\n\\r\\nKirsten Helfer\\r\\nPlease contact: helferkirsten@gmail.com\"}}', '193.108.118.49', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-05-26 04:03:20', '2026-05-26 04:03:20', 'pending'),
