(87, NULL, 14, 1, 31, 9, 9, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Cristine Taylor\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"marketing@technodreamoutsourcing.com\"},\"subject\":{\"field_name\":\"Subject\",\"field_type\":\"Input\",\"value\":\"Collaborations\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello, I am Cristine, a web development manager at Technodream Web Design in Las Vegas, the largest overseas web development company that has been partnering with other web development businesses in the United States since 2008, with an office in Baguio City in the Philippines. We hire highly-skilled graphic designers and programmers that can use platforms such as Shopify, WordPress, WooCommerce, Joomla, Xcarts, HTML5, CCS3, JavaScript, and PHP to develop responsive websites. We are very flexible, and we have very competitive starting prices for the following services to give you an idea. Basic WordPress and responsive site (up to 10 pages) start at USD 800, search engine optimization and social media marketing at USD 300 each, data entry at USD 20 per hour, and other requested features at USD 30 per hour. Just let me know if you want to see some samples of websites for your client\'s business. We aim to form mutually profitable and long-lasting partnerships with our clients. Thank you very much. We look forward to working with you. You may reach out to us at (702) 940-9731 x 8026 or marketing@technodreamoutsourcing.com.\"}}', '108.181.57.82', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-01 01:27:07', '2026-06-01 01:27:07', 'pending'),
(88, NULL, 14, 1, 31, 9, 9, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Cristine Taylor\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"marketing@technodreamoutsourcing.com\"},\"subject\":{\"field_name\":\"Subject\",\"field_type\":\"Input\",\"value\":\"Collaborations\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello, I am Cristine, a web development manager at Technodream Web Design in Las Vegas, the largest overseas web development company that has been partnering with other web development businesses in the United States since 2008, with an office in Baguio City in the Philippines. We hire highly-skilled graphic designers and programmers that can use platforms such as Shopify, WordPress, WooCommerce, Joomla, Xcarts, HTML5, CCS3, JavaScript, and PHP to develop responsive websites. We are very flexible, and we have very competitive starting prices for the following services to give you an idea. Basic WordPress and responsive site (up to 10 pages) start at USD 800, search engine optimization and social media marketing at USD 300 each, data entry at USD 20 per hour, and other requested features at USD 30 per hour. Just let me know if you want to see some samples of websites for your client\'s business. We aim to form mutually profitable and long-lasting partnerships with our clients. Thank you very much. We look forward to working with you. You may reach out to us at (702) 940-9731 x 8026 or marketing@technodreamoutsourcing.com.\"}}', '108.181.57.206', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-01 09:05:15', '2026-06-01 09:05:15', 'pending'),
