(98, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Tara Henderson\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"7788093773\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"TARALYNNHENDERSON83@GMAIL.COM\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hi \\r\\nI have a shower door that broke and I need a quote to replace\"}}', '2605:b100:928:46d4:ccc2:c8d7:477:5bf6', 'Mozilla/5.0 (iPhone; CPU iPhone OS 26_3_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) CriOS/148.0.7778.166 Mobile/15E148 Safari/604.1', NULL, '2026-06-06 17:26:12', '2026-06-06 17:26:12', 'pending'),
(99, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Kirsten Helfer\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"09830152514\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"helferkirsten@gmail.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello,\\r\\n\\r\\nI came across your website and really liked what you\'re doing.\\r\\n\\r\\nWhile browsing, I had a few ideas on how the design could be improved to make it more engaging and visually appealing. So I went ahead and created a quick redesign mockup for you. Its completely free.\\r\\n\\r\\nIt\\u2019s just a concept, but it shows how your site could look with a more modern and user-friendly approach.\\r\\n\\r\\nIf you\'re interested, I\\u2019d love to share it with you and get your thoughts.\\r\\n\\r\\nThanks for your time!\\r\\n\\r\\nCheers,\\r\\n\\r\\nKirsten Helfer\\r\\nPlease contact: helferkirsten@gmail.com\"}}', '193.108.116.237', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-08 05:06:33', '2026-06-08 05:06:33', 'pending'),
(100, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Kendrick Marshall\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"09830152514\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"digisolutionperfect@gmail.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hey there,\\r\\n\\r\\nHope you and your business are doing well. We\'ve all been through so much this year!\\r\\n\\r\\nI\'m really sorry to bother you, and I know you are super busy, but I have been checking your website, and it seems that you are not ranking well for your ad words and key phrases. I actually help businesses like yours get a better ranking in google by using 10 proven techniques below.\\r\\n\\r\\nI would really love the opportunity to work with you and your business, and bring your website to the top of Google\\u2019s list - the sweet spot where you get clicks and more business!\\r\\n\\r\\nPlease let me tell you some of the techniques that I can use below to help you get a better ranking in google search:\\r\\n\\r\\n1. Title Tag Optimizations are missing, I can add these to your site.\\r\\n2. Meta Tag Optimization descriptions are absent, I can add them too.\\r\\n3. Heading Tags Optimization - No problem getting those put in there.\\r\\n4. Targeted keywords are not placed into tags correctly.\\r\\n5. Alt \\/ Image tags Optimization is not present - it would take me seconds to write these.\\r\\n6. Google Publisher is missing; I can set this up for you 7. Custom 404 Page is missing and I can create this for you.\\r\\n8. The Products are not following Structured mark-up data, let me edit that in google webmaster tools.\\r\\n9. Website Speed Development (Both Mobile and Desktop) I can make some tweaks and show you a speed performance using GTMetrics or Pingdom.\\r\\n10.Content Creation SEO work - As a native English speaker, I can create fantastic articles that people will want to read and share, these will bring business to you by word of mouth rather than expensive promotion via google paid search.\\r\\n\\r\\nI\'m sorry if this sounds a little technical, but rest assured, these techniques will certainly improve you ranking in search. I am so confident that I will offer you a full refund of my fee should you not see an improvement in your google ranking within two months.\\r\\n\\r\\nWe\'ve got lots to do together to make you stand out!\\r\\nPlease give us the chance to work with you. You can see our rates on our website.\\r\\n\\r\\nIf this email has reached you by mistake, or if you do not wish to take advantage of this opportunity, please accept my apologies for any inconvenience caused. We are a small business and we are just trying to get some customers. I\'m sure you were in our position once too. Rest assured that we will not contact you again should you reply to this email with the word \'unsubscribe\'\\r\\n\\r\\nThank you kindly for your time and consideration,\\r\\n\\r\\nLooking forward to working with you.\\r\\n\\r\\nKindest regards,\\r\\nKendrick Marshall\"}}', '23.160.72.194', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-09 12:36:43', '2026-06-09 12:36:43', 'pending'),
(101, 13, 16, 13, 58, 30, 39, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"pally\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Number\",\"value\":\"9876908138\"},\"email_address\":{\"field_name\":\"Email Address\",\"field_type\":\"Input\",\"value\":\"kanwar.seo@gmail.com\"},\"choose_service_type\":{\"field_name\":\"Choose Service type\",\"field_type\":\"Select\",\"value\":\"Corporate Security\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Testtinngg\"}}', '124.253.97.112', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-09 12:53:10', '2026-06-09 12:53:10', 'pending'),
(102, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"James Robertson\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"2508648988\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"jamie.2001@shaw.ca\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"I want to have a small electric fireplace supplied & installed in our primary bedroom.  I will need it boxed out\\/drywalled\\/trimmed out and ready for paint.  I want to do this in Dec\\/Jan.  This is a small job.  Please contact when you have some time.\\r\\n\\r\\nRegards,\\r\\n\\r\\nJames\"}}', '174.4.112.50', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-09 22:39:35', '2026-06-09 22:39:35', 'pending'),
(103, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Ashton Miller\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"2508266867\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"Info@ashtonmillerdesign.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hi there,\\r\\n\\r\\nI\\u2019m reaching out on behalf of my parents, who recently experienced a flood and are currently going through the insurance claims process.\\r\\n\\r\\nThey are looking for a contractor who can review the existing insurance scope\\/quote, which we believe is significantly under-quoted. \\r\\n\\r\\nThe project will include both:\\r\\n\\r\\n* Flood restoration work required to return the home to its pre-loss condition\\r\\n* Additional renovation scope (separate from the insurance claim)\\r\\n\\r\\nI am an interior designer and will be assisting with the design. \\r\\n\\r\\nIf this is something you can assist with, please let us know your availability and process for reviewing insurance scopes and providing a second opinion or revised estimate.\\r\\n\\r\\nThanks, Ashton\"}}', '2001:569:5269:eb00:1c9:2f57:7ce:564b', 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.5 Mobile/15E148 Safari/604.1', NULL, '2026-06-10 05:42:26', '2026-06-10 05:42:26', 'pending'),
