(113, NULL, 14, 1, 31, 9, 9, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Derek Hale\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"estimator.derekhale@gmail.com\"},\"subject\":{\"field_name\":\"Subject\",\"field_type\":\"Input\",\"value\":\"Want Estimate, Send us Plans\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hi,\\r\\n\\r\\nI\\u2019m Derek Hale from All Pro Estimation LLC. We provide accurate and reliable painting estimating and material take-off services for residential, commercial, and industrial projects, including new construction, renovations, remodels, tenant improvements, and repainting projects.\\r\\n\\r\\nOur services cover interior and exterior painting, wall coatings, ceiling finishes, primers, sealers, specialty coatings, epoxy coatings, protective coatings, textured finishes, staining, varnishing, waterproof coatings, surface preparation, patching, caulking, painting accessories, finish schedules, and complete Bills of Materials (BOMs).\\r\\n\\r\\nWe are committed to delivering precise estimates and quantity take-offs to help painting contractors, general contractors, developers, property managers, and builders bid confidently, control costs, and improve project planning.\\r\\n\\r\\nFeel free to send your project drawings\\/plans for a quick review and competitive quote.\\r\\n\\r\\nBest regards,\\r\\n\\r\\nDerek Hale\\r\\nPainting Estimator\\r\\nAll Pro Estimation LLC\"}}', '43.251.252.73', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36', NULL, '2026-06-15 22:24:02', '2026-06-15 22:24:02', 'pending'),
