(116, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Leo James\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"6469304111\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"estimate.leojames@gmail.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello,\\r\\n\\r\\nHope you\\u2019re doing well.\\r\\n\\r\\nWe provide accurate electrical estimates for residential and commercial projects.\\r\\n\\r\\nOur estimates include detailed take-offs for conduits, wiring, cables, panels, switchboards, circuit breakers, transformers, lighting fixtures, receptacles, switches, junction boxes, cable trays, conduits and fittings, grounding systems, fire alarm systems, low-voltage systems, emergency lighting, generators, disconnects, raceways, connectors, supports, and other related electrical materials and components.\\r\\n\\r\\nLet me know if you\\u2019d like details on pricing or turnaround time.\\r\\n\\r\\nBest regards,\\r\\nLeo James\"}}', '103.145.185.117', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', NULL, '2026-06-16 16:26:34', '2026-06-16 16:26:34', 'pending'),
