(170, 13, 21, 13, 74, 38, 72, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Karen Howells\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"07984375222\"},\"enter_email\":{\"field_name\":\"Enter email\",\"field_type\":\"Input\",\"value\":\"kaarenhowells@yahoo.co.uk\"},\"service_needed\":{\"field_name\":\"Service Needed\",\"field_type\":\"Select\",\"value\":\"Boiler Service\\/Repair\"},\"brief_details\":{\"field_name\":\"Brief Details\",\"field_type\":\"Text Area\",\"value\":\"Hi, I thought I\'d booked a service yesterdfay, but it seems I didn\'t. I have a Vaillant boiler with an unvented hot water cylinder which is continuously discahrging through the tundish. It is running constantly. I\'ve had to divert the water away from the house. The discharge stops when the mains water is turned off. The boiler pressure is 1.6 bar . Do you have a slot for an engineer to come out soon.  Can you give me a quote\"}}', '2a02:c7c:b230:900:d10b:d04f:c3ad:3ace', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', NULL, '2026-07-28 08:38:32', '2026-07-28 08:38:32', 'pending'),
(171, 13, 19, 13, 43, 18, 26, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Richard Bond\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"09830152514\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"richardmktbond@gmail.com\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello,\\r\\n\\r\\nI came across your website and really liked what you\'re doing.\\r\\n\\r\\nWhile browsing, I had a few ideas on how the design could be improved to make it more engaging and visually appealing. So I went ahead and created a quick redesign mockup for you.Its completely free.\\r\\n\\r\\nIt\\u2019s just a concept, but it shows how your site could look with a more modern and user-friendly approach.\\r\\n\\r\\nIf you\'re interested, I\\u2019d love to share it with you and get your thoughts.\\r\\n\\r\\nThanks for your time!\\r\\n\\r\\nCheers,\\r\\nRichard Bond\"}}', '2407:cb00:c491:9810:6cbd:8fba:4606:b121', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-07-29 04:47:06', '2026-07-28 12:34:27', '2026-07-29 04:47:06', 'pending'),
