(174, 13, 15, 13, 49, 23, 75, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Gaurav sharma\"},\"mobile_number\":{\"field_name\":\"Mobile Number\",\"field_type\":\"Number\",\"value\":\"7705029919\"},\"email\":{\"field_name\":\"Email\",\"field_type\":\"Input\",\"value\":\"np9850571@gmail.com\"},\"service_required\":{\"field_name\":\"Service Required\",\"field_type\":\"Select\",\"value\":\"Landing Page\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hi Team,\\r\\n\\r\\nWe are looking to get a business\\/company website developed for our company. We need a professional website with around 5-8 pages (Home, About Us, Services, Contact Us, and a couple of additional pages as needed).\\r\\n\\r\\nWe are currently comparing quotes from a few developers\\/agencies before finalizing, so it would be really helpful if you could share the following details at the earliest:\\r\\n\\r\\n1. Estimated pricing\\/budget for the complete website\\r\\n2. Approximate delivery timeline\\r\\n3. Whether hosting and domain setup are included in the package\\r\\n4. Link to your previous work\\/portfolio (if available)\\r\\n\\r\\nNote: Please respond only via email at dnda61614@gmail.com \\u2014 kindly do not call, as we are currently only accepting quotes\\/details through email.\\r\\n\\r\\nWe are looking to finalize this on priority, so a quick response at the earliest would be highly appreciated.\\r\\n\\r\\nThanks & Regards,\\r\\nGaurav Sharma\\r\\ndnda61614@gmail.com\"}}', '2405:201:6003:a32:d50a:6b4f:c288:fdfb', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', NULL, '2026-07-31 11:40:17', '2026-07-31 11:40:17', 'pending'),
(175, 13, 21, 13, 74, 38, 72, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Mukesh\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Input\",\"value\":\"07926122642\"},\"enter_email\":{\"field_name\":\"Enter email\",\"field_type\":\"Input\",\"value\":\"mk_in@hotmail.com\"},\"service_needed\":{\"field_name\":\"Service Needed\",\"field_type\":\"Select\",\"value\":\"Bathrooms\"},\"brief_details\":{\"field_name\":\"Brief Details\",\"field_type\":\"Text Area\",\"value\":\"Plumber Needed: Fix Leak Under Ensuite Shower ( Tray \\/ doors - not sure)\\r\\n\\r\\nJob Description:\\r\\nI am looking for a qualified local plumber to investigate and fix an active leak coming from underneath our ensuite shower tray in Reading (RG1 8QS). Water is escaping below the unit. \\r\\n\\r\\nScope of Work:\\r\\n- Gain access to the space underneath the shower tray.\\r\\n- Inspect, repair, or replace the leaking waste trap, drain washer, or underground waste pipe.\\r\\n- Once the internal plumbing is completely watertight, strip and replace the old silicone around the tray and side doors to ensure a professional, waterproof finish.\\r\\n\\r\\nRequirements:\\r\\n- Fully qualified plumber with active Public Liability Insurance.\\r\\n- Experience with under-shower leak detection and neat sanitary sealing.\\r\\n- Please provide your call-out fee, hourly rate, or an estimated fixed price.\\r\\n\\r\\nAvailability: Urgent \\/ As soon as possible.\"}}', '82.132.185.143', 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.6 Mobile/15E148 Safari/604.1', '2026-08-03 17:21:38', '2026-07-31 16:24:43', '2026-08-03 17:21:38', 'pending'),
(176, 13, 16, 13, 58, 30, 39, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"sajjad hussain\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Number\",\"value\":\"07466049802\"},\"email_address\":{\"field_name\":\"Email Address\",\"field_type\":\"Input\",\"value\":\"sajjadhussain03199@gmail.com\"},\"choose_service_type\":{\"field_name\":\"Choose Service type\",\"field_type\":\"Select\",\"value\":\"Retail Security\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hello Manager\\r\\nI hope you are doing well. My name is Sajjad Hussain and I am interested in joining your security team. I hold a valid SIA Door Supervisor licence and am a reliable professional and hardworking individual with strong customer service and conflict management skills.\\r\\nI would be grateful if you could consider me for any current or upcoming Security Officer Door Supervisor or Event Security vacancies. I am available to start immediately and am willing to work flexible shifts, including nights and weekends.\\r\\nThank you for your time and consideration. I look forward to hearing from you.\\r\\nKind regards\\r\\nSajjad Hussain\"}}', '2a00:23c5:7a92:c701:5919:fbd9:301a:fcea', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', NULL, '2026-08-01 13:00:00', '2026-08-01 13:00:00', 'pending'),
(177, 13, 16, 13, 58, 30, 39, '{\"name\":{\"field_name\":\"Name\",\"field_type\":\"Input\",\"value\":\"Rachel Wilson\"},\"phone_number\":{\"field_name\":\"Phone number\",\"field_type\":\"Number\",\"value\":\"09830152514\"},\"email_address\":{\"field_name\":\"Email Address\",\"field_type\":\"Input\",\"value\":\"rachelwilsonrachel4@gmail.com\"},\"choose_service_type\":{\"field_name\":\"Choose Service type\",\"field_type\":\"Select\",\"value\":\"Retail Security\"},\"message\":{\"field_name\":\"Message\",\"field_type\":\"Text Area\",\"value\":\"Hope you are doing well.\\r\\n\\r\\nI have been checking your website quite often. We\'ve noticed the main keywords are still not in the top 10 Google searches. Also, your website is missing traffic from Google AI overviews, ChatGPT and other AI tools.\\r\\n\\r\\nSince the introduction of AI, the optimization process of a website or business has changed a lot.\\r\\n \\r\\nSo I would like to have the opportunity to work for you, and we are providing improvement of organic traffic and traffic from AI prompts with a guaranteed period.\\r\\n\\r\\nI have found out that there are a few things that need to be done for better performance.\\r\\nLet me tell you some of them -\\r\\n\\r\\n1. Title Tag Optimization ( Directly impacting Google\\u2019s Search Positions )\\r\\n2. Meta Tag Optimization (Description, and other meta elements)\\r\\n3. Heading Tags Optimization with keywords\\r\\n4. Targeted keywords are not placed properly in the content\\r\\n5. Alt \\/ Image tags Optimization\\r\\n6. LLMS.txt Missing ( Directly impacting the AI Answer visibility )\\r\\n7. Custom 404 Page is missing\\r\\n8. Proper Structured Data Markup Missing\\r\\n9. Website Speed Development (Both Mobile and Desktop )\\r\\nPlease check via Google Developer -\\r\\nhttps:\\/\\/developers.google.com\\/speed\\/pagespeed\\/\\r\\n10. Off \\u2013Page SEO work\\r\\n\\r\\nAnd more \\u2026\\u2026\\u2026\\u2026\\u2026..\\r\\n\\r\\nYou can see these are the things that need to be done properly to make the keywords get into the top 10 spot in Google Search and increase sales\\/leads.\\r\\n\\r\\nPlease give us a chance to fix these errors, and we will give you top 10 rank for your keywords and improve AI visibility.\\r\\n\\r\\nPlease let me know if you encounter any problems or if there is anything you need. If this email has reached you by mistake or if you do not wish to take advantage of this free advertising opportunity, please accept my apology for any inconvenience caused and rest assured that you will not be contacted again.\\r\\n\\r\\nMany thanks for your time and consideration,\\r\\nLooking forward\\r\\nRegards\\\"\\r\\nRachel Wilson\"}}', '103.102.116.78', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-08-03 17:14:13', '2026-08-03 09:15:07', '2026-08-03 17:14:13', 'pending'),
